// src/GDAL7_warp.cpp
// Manual file - NOT generated by orchestrate.R
// Warping a dataset onto a grid with GDAL's warp API, no utility layer:
// GDALCreateGenImgProjTransformer2, GDALCreateApproxTransformer,
// GDALWarpOptions and GDALWarpOperation::ChunkAndWarpImage, into a MEM
// dataset. The nativeRaster form warps straight into the R vector: its four
// bytes per pixel are the MEM dataset's four bands.

#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

#include "gdal7.h"
#include "gdal_alg.h"
#include "gdalwarper.h"
#include "ogr_srs_api.h"

namespace {

inline GDALDatasetH dataset(SEXP xp) {
    return gdal7::get<GDALDatasetH>(xp, gdal7::Kind::Dataset);
}

// gdalwarp's -r names, plus "nearest" as read_raster() spells it.
GDALResampleAlg warp_resample(const std::string& r) {
    const char* s = r.c_str();
    if (EQUAL(s, "near") || EQUAL(s, "nearest")) return GRA_NearestNeighbour;
    if (EQUAL(s, "bilinear")) return GRA_Bilinear;
    if (EQUAL(s, "cubic")) return GRA_Cubic;
    if (EQUAL(s, "cubicspline")) return GRA_CubicSpline;
    if (EQUAL(s, "lanczos")) return GRA_Lanczos;
    if (EQUAL(s, "average")) return GRA_Average;
    if (EQUAL(s, "rms")) return GRA_RMS;
    if (EQUAL(s, "mode")) return GRA_Mode;
    if (EQUAL(s, "max")) return GRA_Max;
    if (EQUAL(s, "min")) return GRA_Min;
    if (EQUAL(s, "med")) return GRA_Med;
    if (EQUAL(s, "q1")) return GRA_Q1;
    if (EQUAL(s, "q3")) return GRA_Q3;
    if (EQUAL(s, "sum")) return GRA_Sum;
    cpp11::stop("Unknown resampling algorithm '%s'. One of: nearest, bilinear, cubic, "
                "cubicspline, lanczos, average, rms, mode, max, min, med, q1, q3, sum",
                s);
}

// Any CRS PROJ understands, as WKT for the transformer. Called inside an
// ErrorScope, so PROJ's message becomes part of the R error.
std::string crs_wkt(const std::string& crs, gdal7::ErrorScope& err) {
    OGRSpatialReferenceH srs = OSRNewSpatialReference(nullptr);
    std::string out;
    if (OSRSetFromUserInput(srs, crs.c_str()) == OGRERR_NONE) {
        char* wkt = nullptr;
        if (OSRExportToWkt(srs, &wkt) == OGRERR_NONE && wkt) out = wkt;
        CPLFree(wkt);
    }
    OSRDestroySpatialReference(srs);
    if (out.empty()) err.stop("`crs` '" + crs + "' is not a CRS GDAL understands");
    return out;
}

// The pieces of a warp that need freeing, whichever way the call ends.
struct Warp {
    void* transformer = nullptr;
    GDALWarpOptions* options = nullptr;
    GDALDatasetH dst = nullptr;
    ~Warp() {
        if (options) {
            options->hSrcDS = nullptr;
            options->hDstDS = nullptr;
            options->pTransformerArg = nullptr;
            GDALDestroyWarpOptions(options);
        }
        if (transformer) GDALDestroyApproxTransformer(transformer);
        if (dst) GDALClose(dst);
    }
};

// Set up the transformer and warp options from `src` onto `dst` (already
// created, with its geotransform and CRS), for the given band mapping.
void setup(Warp& w, GDALDatasetH src, const std::string& wkt, const double gt[6],
           const std::string& resample, double error_threshold,
           const std::vector<int>& src_bands, const std::vector<int>& dst_bands,
           int src_alpha, int dst_alpha, bool init_nodata, gdal7::ErrorScope& err) {
    char** to = CSLSetNameValue(nullptr, "DST_SRS", wkt.c_str());
    void* gen = GDALCreateGenImgProjTransformer2(src, nullptr, to);
    CSLDestroy(to);
    if (!gen) err.stop("Could not create a transformer from the source to `crs`");
    GDALSetGenImgProjTransformerDstGeoTransform(gen, gt);
    w.transformer = GDALCreateApproxTransformer(GDALGenImgProjTransform, gen, error_threshold);
    GDALApproxTransformerOwnsSubtransformer(w.transformer, TRUE);

    GDALWarpOptions* o = GDALCreateWarpOptions();
    w.options = o;
    o->hSrcDS = src;
    o->hDstDS = w.dst;
    o->eResampleAlg = warp_resample(resample);
    o->pfnTransformer = GDALApproxTransform;
    o->pTransformerArg = w.transformer;
    const int nb = static_cast<int>(src_bands.size());
    o->nBandCount = nb;
    o->panSrcBands = static_cast<int*>(CPLMalloc(sizeof(int) * nb));
    o->panDstBands = static_cast<int*>(CPLMalloc(sizeof(int) * nb));
    bool any_nodata = false;
    std::vector<double> nd(nb, 0.0);
    std::vector<int> has(nb, 0);
    for (int i = 0; i < nb; i++) {
        o->panSrcBands[i] = src_bands[i];
        o->panDstBands[i] = dst_bands[i];
        nd[i] = GDALGetRasterNoDataValue(GDALGetRasterBand(src, src_bands[i]), &has[i]);
        any_nodata = any_nodata || has[i];
    }
    if (any_nodata) {
        // as gdalwarp: the source's nodata, carried to the destination
        o->padfSrcNoDataReal = static_cast<double*>(CPLMalloc(sizeof(double) * nb));
        o->padfDstNoDataReal = static_cast<double*>(CPLMalloc(sizeof(double) * nb));
        for (int i = 0; i < nb; i++) {
            o->padfSrcNoDataReal[i] = has[i] ? nd[i] : -1.1e20;
            o->padfDstNoDataReal[i] = o->padfSrcNoDataReal[i];
            if (has[i] && init_nodata) {
                GDALSetRasterNoDataValue(GDALGetRasterBand(w.dst, dst_bands[i]), nd[i]);
            }
        }
    }
    o->papszWarpOptions = CSLSetNameValue(o->papszWarpOptions, "INIT_DEST",
                                          any_nodata && init_nodata ? "NO_DATA" : "0");
    o->nSrcAlphaBand = src_alpha;
    o->nDstAlphaBand = dst_alpha;
}

void run(Warp& w, int nx, int ny, gdal7::ErrorScope& err) {
    GDALWarpOperation op;
    if (op.Initialize(w.options) != CE_None) err.stop("Could not set up the warp");
    if (op.ChunkAndWarpImage(0, 0, nx, ny) != CE_None) err.stop("The warp failed");
}

int resolve_alpha(GDALDatasetH src, const std::vector<int>& bands, int alpha_band) {
    if (alpha_band >= 0) return alpha_band;  // 0 is none, k is band k
    // -1: as gdalwarp, the source's last band if it is an alpha band and
    // among those asked for
    const int last = GDALGetRasterCount(src);
    if (last > 1 && GDALGetRasterColorInterpretation(GDALGetRasterBand(src, last)) == GCI_AlphaBand) {
        for (int b : bands) if (b == last) return last;
    }
    return 0;
}

std::vector<int> check_bands(GDALDatasetH src, cpp11::integers bands) {
    const int count = GDALGetRasterCount(src);
    std::vector<int> out;
    for (int b : bands) {
        if (b == NA_INTEGER || b < 1 || b > count) {
            cpp11::stop("`bands` must be between 1 and %d", count);
        }
        out.push_back(b);
    }
    if (out.empty()) cpp11::stop("`bands` is empty");
    return out;
}

}  // namespace

// Warp bands of a dataset onto a grid: a list of one row-major vector per
// band, in the R type asked for.
[[cpp11::register]]
cpp11::list GDAL7_dataset_warp(SEXP xp, std::string crs, cpp11::doubles geotransform,
                               cpp11::integers size, std::string resample,
                               cpp11::integers bands, std::string type,
                               double error_threshold, int alpha_band) {
    GDALDatasetH src = dataset(xp);
    const std::vector<int> b = check_bands(src, bands);
    if (geotransform.size() != 6) cpp11::stop("`geotransform` is 6 numbers");
    if (size.size() != 2 || size[0] < 1 || size[1] < 1) cpp11::stop("`size` is 2 positive integers");
    double gt[6];
    for (int i = 0; i < 6; i++) gt[i] = geotransform[i];
    const int nx = size[0], ny = size[1];
    gdal7::ErrorScope err;
    const std::string wkt = crs_wkt(crs, err);

    GDALDataType buf_type;
    SEXPTYPE sexp;
    if (type == "double") { buf_type = GDT_Float64; sexp = REALSXP; }
    else if (type == "integer") { buf_type = GDT_Int32; sexp = INTSXP; }
    else if (type == "raw") { buf_type = GDT_Byte; sexp = RAWSXP; }
    else cpp11::stop("`type` is one of \"double\", \"integer\" or \"raw\"");
    for (int k : b) {
        const GDALDataType t = GDALGetRasterDataType(GDALGetRasterBand(src, k));
        const bool fits_raw = t == GDT_Byte;
        const bool fits_int = fits_raw || t == GDT_Int8 || t == GDT_Int16 || t == GDT_UInt16 || t == GDT_Int32;
        if ((sexp == RAWSXP && !fits_raw) || (sexp == INTSXP && !fits_int)) {
            cpp11::stop("Band %d holds %s, which does not fit R's %s; warp it as \"double\"",
                        k, GDALGetDataTypeName(t), sexp == RAWSXP ? "raw" : "integer");
        }
    }

    Warp w;
    // the destination keeps the source's type, as gdalwarp's output would,
    // so the kernel works in the same type; the R type is applied on reading
    const GDALDataType work = GDALGetRasterDataType(GDALGetRasterBand(src, b[0]));
    const int nb = static_cast<int>(b.size());
    w.dst = GDALCreate(GDALGetDriverByName("MEM"), "", nx, ny, nb, work, nullptr);
    if (!w.dst) err.stop("Could not create the destination");
    GDALSetGeoTransform(w.dst, gt);
    GDALSetProjection(w.dst, wkt.c_str());
    std::vector<int> dst_bands(nb);
    for (int i = 0; i < nb; i++) dst_bands[i] = i + 1;
    const int alpha = resolve_alpha(src, b, alpha_band);
    setup(w, src, wkt, gt, resample, error_threshold, b, dst_bands, alpha, 0, true, err);
    run(w, nx, ny, err);

    cpp11::writable::list out(nb);
    cpp11::writable::strings names(nb);
    for (int i = 0; i < nb; i++) {
        cpp11::sexp v(Rf_allocVector(sexp, static_cast<R_xlen_t>(nx) * ny));
        void* data = sexp == REALSXP ? static_cast<void*>(REAL(v))
                   : sexp == INTSXP ? static_cast<void*>(INTEGER(v)) : static_cast<void*>(RAW(v));
        if (GDALRasterIO(GDALGetRasterBand(w.dst, i + 1), GF_Read, 0, 0, nx, ny, data,
                         nx, ny, buf_type, 0, 0) != CE_None) {
            err.stop("Could not read the warped band");
        }
        out[i] = v;
        names[i] = std::to_string(b[i]);
    }
    out.names() = names;
    err.flush();
    return out;
}

// Warp Byte bands into a nativeRaster: one R integer per pixel,
// R | G << 8 | B << 16 | A << 24 (little-endian), row-major. The warp writes a
// four-band MEM dataset; one GDALDatasetRasterIO with a pixel spacing of 4 and
// a band spacing of 1 then interleaves it into the vector, so the packing is
// GDAL's, with nothing done in R. One band is grey (warped into R, G and B),
// three are RGB, and a source alpha band masks; the alpha byte is the
// destination alpha GDAL computes (0 where no source pixel contributes).
//
// (MEM bands created over the vector with DATAPOINTER, to skip that one copy,
// crashed on GDAL 3.12 in CI; the spaced read is the documented way.)
[[cpp11::register]]
SEXP GDAL7_dataset_warp_nara(SEXP xp, std::string crs, cpp11::doubles geotransform,
                             cpp11::integers size, std::string resample,
                             cpp11::integers bands, double error_threshold, int alpha_band) {
    GDALDatasetH src = dataset(xp);
    const std::vector<int> b = check_bands(src, bands);
    if (geotransform.size() != 6) cpp11::stop("`geotransform` is 6 numbers");
    if (size.size() != 2 || size[0] < 1 || size[1] < 1) cpp11::stop("`size` is 2 positive integers");
    for (int k : b) {
        if (GDALGetRasterDataType(GDALGetRasterBand(src, k)) != GDT_Byte) {
            cpp11::stop("A nativeRaster holds bytes; band %d is %s", k,
                        GDALGetDataTypeName(GDALGetRasterDataType(GDALGetRasterBand(src, k))));
        }
    }
    {
        const uint16_t one = 1;
        if (*reinterpret_cast<const uint8_t*>(&one) != 1) {
            cpp11::stop("nativeRaster packing here assumes a little-endian machine");  // # nocov
        }
    }
    double gt[6];
    for (int i = 0; i < 6; i++) gt[i] = geotransform[i];
    const int nx = size[0], ny = size[1];
    gdal7::ErrorScope err;
    const std::string wkt = crs_wkt(crs, err);

    const int alpha = resolve_alpha(src, b, alpha_band);
    std::vector<int> colour;
    for (int k : b) if (k != alpha) colour.push_back(k);
    std::vector<int> src_bands, dst_bands;
    if (colour.size() == 1) {
        src_bands = {colour[0], colour[0], colour[0]};
        dst_bands = {1, 2, 3};
    } else if (colour.size() == 3) {
        src_bands = colour;
        dst_bands = {1, 2, 3};
    } else {
        cpp11::stop("A nativeRaster is grey (1 band) or RGB (3 bands), plus an optional alpha band");
    }

    cpp11::sexp out(Rf_allocVector(INTSXP, static_cast<R_xlen_t>(nx) * ny));
    std::fill(INTEGER(out), INTEGER(out) + static_cast<R_xlen_t>(nx) * ny, 0);
    GByte* base = reinterpret_cast<GByte*>(INTEGER(out));

    Warp w;
    w.dst = GDALCreate(GDALGetDriverByName("MEM"), "", nx, ny, 4, GDT_Byte, nullptr);
    if (!w.dst) err.stop("Could not create the destination");
    GDALSetGeoTransform(w.dst, gt);
    GDALSetProjection(w.dst, wkt.c_str());
    // no destination nodata: the alpha byte (band 4) says where there is data
    setup(w, src, wkt, gt, resample, error_threshold, src_bands, dst_bands, alpha, 4, false, err);
    run(w, nx, ny, err);

    // interleave the four bands into the nativeRaster's bytes
    int band_map[4] = {1, 2, 3, 4};
    if (GDALDatasetRasterIO(w.dst, GF_Read, 0, 0, nx, ny, base, nx, ny, GDT_Byte, 4, band_map,
                            4, static_cast<GSpacing>(nx) * 4, 1) != CE_None) {
        err.stop("Could not read the warped bands into the nativeRaster");
    }
    err.flush();

    cpp11::writable::integers dim({ny, nx});
    Rf_setAttrib(out, R_DimSymbol, dim);
    Rf_setAttrib(out, Rf_install("channels"), Rf_ScalarInteger(4));
    Rf_setAttrib(out, R_ClassSymbol, Rf_mkString("nativeRaster"));
    return out;
}
